import React, { useRef, useEffect, useState, useCallback } from "react";
import "./App.css";

// LIBRERÍA CIENTÍFICA PARA RENDERIZAR LATEX
import 'katex/dist/katex.min.css';
import { BlockMath } from 'react-katex';

function App() {
  const canvasRef = useRef(null);
  const LIMITE = 8.5;

  // Estados del jugador (Sonda de Diagnóstico 🛸)
  const [pos, setPos] = useState({ re: -2, im: 3 }); 
  const [mensaje, setMensaje] = useState("");

  // CONFIGURACIÓN INTERACTIVA DEL CIRCUITO RLC
  const [R, setR] = useState(2.0); // Resistencia (Ω) -> Afecta la parte Real (α)
  const [L, setL] = useState(1.0); // Inductancia (H)
  const [C, setC] = useState(0.1); // Capacitancia (F) -> Afecta la parte Imaginaria (ω)

  // Polos complejos calculados en el plano S (Laplace)
  const [polos, setPolos] = useState([]);
  const [tipoRespuesta, setTipoRespuesta] = useState("");

  // Modales e historial LaTeX para verificar el Teorema del Residuo
  const [historialLatex, setHistorialLatex] = useState([]);
  const [mostrarModal, setMostrarModal] = useState(false);

  const aviso = (txt) => {
    setMensaje(txt);
    setTimeout(() => setMensaje(""), 2500);
  };

  // --- 1. CÁLCULO EN TIEMPO REAL DE LOS POLOS COMPLEJOS (RLC) ---
  // Ecuación característica: s^2 + (R/L)s + 1/(LC) = 0
  useEffect(() => {
    const alpha = R / (2 * L);           // Factor de atenuación (Parte Real)
    const omega02 = 1 / (L * C);         // Frecuencia natural no amortiguada al cuadrado
    const discriminante = (alpha * alpha) - omega02;

    let nuevosPolos = [];
    let tipo = "";

    if (discriminante < 0) {
      // Caso Subamortiguado: Polos complejos conjugados (Oscilaciones periódicas)
      const wd = Math.sqrt(omega02 - (alpha * alpha));
      nuevosPolos = [
        { re: -alpha, im: wd },
        { re: -alpha, im: -wd }
      ];
      tipo = "SUBAMORTIGUADO (Oscilaciones Transitorias)";
    } else if (discriminante > 0) {
      // Caso Sobreamortiguado: Dos polos reales puros (Sin oscilación, caída lenta)
      const r1 = -alpha + Math.sqrt(discriminante);
      const r2 = -alpha - Math.sqrt(discriminante);
      nuevosPolos = [
        { re: r1, im: 0 },
        { re: r2, im: 0 }
      ];
      tipo = "SOBREAMORTIGUADO (Respuesta Lenta Sin Oscilación)";
    } else {
      // Caso Críticamente Amortiguado: Polos reales repetidos (Retorno rápido al equilibrio)
      nuevosPolos = [
        { re: -alpha, im: 0 },
        { re: -alpha, im: 0 }
      ];
      tipo = "CRÍTICAMENTE AMORTIGUADO (Estabilización Óptima)";
    }

    setPolos(nuevosPolos);
    setTipoRespuesta(tipo);
  }, [R, L, C]);

  // --- CAPTURA DE TECLADO (MOVIMIENTO DE LA SONDA 🛸) ---
  useEffect(() => {
    const manejarTeclado = (e) => {
      const paso = 0.4;
      if (e.key === "ArrowUp") setPos(prev => ({ ...prev, im: Math.min(LIMITE, +(prev.im + paso).toFixed(2)) }));
      if (e.key === "ArrowDown") setPos(prev => ({ ...prev, im: Math.max(-LIMITE, +(prev.im - paso).toFixed(2)) }));
      if (e.key === "ArrowLeft") setPos(prev => ({ ...prev, re: Math.max(-LIMITE, +(prev.re - paso).toFixed(2)) }));
      if (e.key === "ArrowRight") setPos(prev => ({ ...prev, re: Math.min(LIMITE, +(prev.re + paso).toFixed(2)) }));
    };
    window.addEventListener("keydown", manejarTeclado);
    return () => window.removeEventListener("keydown", manejarTeclado);
  }, []);

  // --- 2. EVALUACIÓN DE RESIDUOS MEDIANTE EL TEOREMA DEL RESIDUO ---
  const analizarResiduosLaplace = () => {
    const alpha = R / (2 * L);
    const omega02 = 1 / (L * C);
    const discriminante = (alpha * alpha) - omega02;

    const formulasLatex = [
      `\\mathbf{Función\\; de\\; Transferencia:\\; I(s) = \\frac{V_0/L}{s^2 + \\frac{R}{L}s + \\frac{1}{LC}}}`
    ];

    if (discriminante < 0) {
      const wd = Math.sqrt(omega02 - (alpha * alpha));
      // Suma de residuos para polos simples complejos conjugados por De Moivre / Euler [0]
      formulasLatex.push(`\\text{Polos Conjugados encontrados en: } s = -${alpha.toFixed(2)} \\pm ${wd.toFixed(2)}i`);
      formulasLatex.push(`\\text{Residuo en } s_1:\\; \\lim_{s \\to s_1} (s-s_1)I(s)e^{st} = \\frac{V_0}{2i\\cdot L\\cdot\\omega_d} e^{(- \\alpha + i\\omega_d)t}`);
      formulasLatex.push(`\\mathbf{Teorema\\; del\\; Residuo\\; [i(t) = \\text{Res}_1 + \\text{Res}_2]:}`);
      formulasLatex.push(`i(t) = \\frac{V_0}{L\\cdot\\omega_d} e^{-${alpha.toFixed(2)}t} \\sin(${wd.toFixed(2)}t)`);
    } else {
      // Suma de residuos para polos reales simples o repetidos [0]
      formulasLatex.push(`\\text{Respuesta Temporal del Sistema Dinámico Dinámico via Residuos:}`);
      formulasLatex.push(`i(t) = C_1 e^{s_1 t} + C_2 e^{s_2 t}`);
      formulasLatex.push(`\\mathbf{\\text{El\\; circuito\\; se\\; estabiliza\\; exponencialmente\\; sin\\; oscilar.}}`);
    }

    setHistorialLatex(formulasLatex);
    setMostrarModal(true);
  };
  // --- 3. LOOP GRÁFICO EN CANVAS 2D (PLANO S DE LAPLACE) ---
  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext("2d"); const w = canvas.width; const h = canvas.height;
    
    // Interfaz de consola de reactor nuclear oscuro
    ctx.fillStyle = "#040912"; ctx.fillRect(0, 0, w, h);
    
    const paso = 50; 
    const ox = w / 2 + 100; // Desplazamos el eje imaginario a la derecha para ver mejor el semiplano izquierdo estable
    const oy = h / 2;

    // Rejilla de frecuencias complejas (Plano S)
    ctx.strokeStyle = "rgba(0, 212, 255, 0.02)"; ctx.lineWidth = 1;
    for (let x = -15; x <= 15; x += 1) { let px = ox + x * paso; ctx.beginPath(); ctx.moveTo(px, 0); ctx.lineTo(px, h); ctx.stroke(); }
    for (let y = -15; y <= 15; y += 1) { let py = oy - y * paso; ctx.beginPath(); ctx.moveTo(0, py); ctx.lineTo(w, py); ctx.stroke(); }

    // Ejes Cartesianos Complejos (Eje Real σ y Eje Imaginario jω)
    ctx.strokeStyle = "rgba(0, 212, 255, 0.15)"; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, oy); ctx.lineTo(w, oy); ctx.stroke(); // Eje Real
    ctx.beginPath(); ctx.moveTo(ox, 0); ctx.lineTo(ox, h); ctx.stroke(); // Eje Imaginario

    // Rotular escalas del plano de Laplace
    ctx.fillStyle = "rgba(0, 212, 255, 0.4)"; ctx.font = "12px monospace"; ctx.textAlign = "left";
    for (let x = -15; x <= 5; x += 1) { if (x !== 0) ctx.fillText(x + "σ", ox + x * paso, oy + 18); }
    for (let y = -15; y <= 15; y += 1) { if (y !== 0) ctx.fillText(y + "jω", ox - 40, oy - y * paso); }

    // --- DIBUJAR LOS POLOS DEL CIRCUITO DINÁMICO (CRUCES 'X' DE ENERGÍA) ---
    polos.forEach((p, idx) => {
      const px = ox + p.re * paso;
      const py = oy - p.im * paso;
      const tam = 10;

      ctx.strokeStyle = "#ff3b3b"; ctx.lineWidth = 3;
      ctx.shadowBlur = 15; ctx.shadowColor = "#ff3b3b";
      
      // Dibuja la tradicional marca 'X' de un polo en diagramas de control lineal
      ctx.beginPath(); ctx.moveTo(px - tam, py - tam); ctx.lineTo(px + tam, py + tam); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(px - tam, py + tam); ctx.lineTo(px + tam, py - tam); ctx.stroke();
      
      ctx.shadowBlur = 0;
      ctx.fillStyle = "white"; ctx.font = "11px monospace";
      ctx.fillText(`Polo s_${idx+1}`, px + 15, py + 4);
    });

    // --- NUEVO MINI-GRÁFICO EN TIEMPO REAL: LA RESPUESTA TEMPORAL i(t) ---
    // Muestra en la esquina inferior izquierda la curva real resultante calculada por residuos [0]
    ctx.fillStyle = "rgba(0, 0, 0, 0.5)"; ctx.strokeStyle = "rgba(0, 212, 255, 0.3)";
    ctx.fillRect(20, h - 160, 220, 140); ctx.strokeRect(20, h - 160, 220, 140);

    ctx.strokeStyle = "#00ffaa"; ctx.lineWidth = 2; ctx.beginPath();
    const alpha = R / (2 * L); const omega02 = 1 / (L * C);
    const discriminante = (alpha * alpha) - omega02;

    for (let tPixel = 0; tPixel < 200; tPixel++) {
      const tMat = tPixel * 0.08;
      let amp = 0;

      if (discriminante < 0) {
        const wd = Math.sqrt(omega02 - (alpha * alpha));
        amp = Math.sin(wd * tMat) * Math.exp(-alpha * tMat) * 60; // Curva senoidal amortiguada [0]
      } else {
        amp = (Math.exp((-alpha + 0.5) * tMat) - Math.exp((-alpha - 0.5) * tMat)) * 40; // Curva exponencial pura
      }

      const gx = 30 + tPixel;
      const gy = (h - 90) - amp;
      if (tPixel === 0) ctx.moveTo(gx, gy); else ctx.lineTo(gx, gy);
    }
    ctx.stroke();
    ctx.fillStyle = "white"; ctx.font = "11px monospace";
    ctx.fillText("Respuesta i(t) por Residuos", 30, h - 140);

    // Dibujar la Sonda de Diagnóstico (🛸)
    const jx = ox + pos.re * paso; const jy = oy - pos.im * paso;
    ctx.strokeStyle = "#ffbc00"; ctx.lineWidth = 2.5; ctx.beginPath();
    ctx.arc(jx, jy, 20, 0, Math.PI * 2); ctx.stroke();
    ctx.font = "22px Arial"; ctx.textBaseline = "middle"; ctx.textAlign = "center";
    ctx.fillText("🛸", jx, jy);

    // Datos científicos en pantalla
    ctx.fillStyle = "white"; ctx.font = "13px monospace"; ctx.textAlign = "left";
    ctx.fillText(`Frecuencia Sonda (s) = ${pos.re.toFixed(2)} + ${pos.im.toFixed(2)}jω`, 20, 30);
    ctx.fillText(`Estado del Reactor  = ${tipoRespuesta}`, 20, 50);
  }, [pos, polos, tipoRespuesta, R, L, C]);

  useEffect(() => { draw(); }, [draw]);

  return (
    <div className="game-container">
      {mensaje && <div className="game-message">{mensaje}</div>}

      {/* MODAL CIENTÍFICO RESIDUOS */}
      {mostrarModal && (
        <div className="modal-overlay">
          <div className="modal-content" style={{ width: "650px", background: "#0b1524" }}>
            <button className="modal-close" onClick={() => setMostrarModal(false)}>&times;</button>
            <h2>Teorema del Residuo en Sistemas RLC</h2>
            <div className="modal-body" style={{ color: "white", padding: "15px 0" }}>
              {historialLatex.map((ecuacion, index) => (
                <div key={index} style={{ padding: "10px 0", background: index % 2 === 0 ? "rgba(255,255,255,0.01)" : "transparent" }}>
                  <BlockMath math={ecuacion} />
                </div>
              ))}
            </div>
            <button className="modal-play-btn" onClick={() => setMostrarModal(false)} style={{ background: "#00ffaa", color: "#071426" }}>
              Reanudar Reactor
            </button>
          </div>
        </div>
      )}

      <div className="side-panel">
        <div className="card" style={{ borderTop: "3px solid #ff3b3b" }}>
          <h3>Componentes RLC</h3>
          
          <div style={{ marginBottom: "12px" }}>
            <label>Resistencia R (Amortiguamiento): {R} Ω</label>
            <input type="range" min="0.2" max="6" step="0.1" value={R} onChange={(e) => setR(+e.target.value)} style={{ width: "100%" }} />
          </div>

          <div style={{ marginBottom: "12px" }}>
            <label>Inductancia L (Inercia): {L} H</label>
            <input type="range" min="0.5" max="3" step="0.1" value={L} onChange={(e) => setL(+e.target.value)} style={{ width: "100%" }} />
          </div>

          <div style={{ marginBottom: "12px" }}>
            <label>Capacitancia C (Almacenamiento): {C} F</label>
            <input type="range" min="0.05" max="0.5" step="0.01" value={C} onChange={(e) => setC(+e.target.value)} style={{ width: "100%" }} />
          </div>

          <button onClick={analizarResiduosLaplace} style={{ background: "#00ffaa", color: "#071426", fontWeight: "bold", marginTop: "5px" }}>
            Calcular i(t) por Residuos
          </button>
        </div>
      </div>

      <div className="main-area">
        <canvas ref={canvasRef} width={900} height={650} />
      </div>
    </div>
  );
}

export default App;
